CREATE TABLE player_profile (id BIGINT NOT NULL AUTO_INCREMENT,user_id BIGINT NULL,default_game VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,default_region VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NULL,preferences JSON NOT NULL DEFAULT (JSON_OBJECT()),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_player_profile_user UNIQUE(user_id),CONSTRAINT ck_player_profile_region CHECK(default_region IS NULL OR REGEXP_LIKE(default_region,'^[A-Z0-9_-]{2,16}$','c')),CONSTRAINT fk_player_profile_user FOREIGN KEY(user_id) REFERENCES user_account(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
